import{_ as d,o as r,c as e,a2 as o}from"./chunks/framework.CeYlivdO.js";const u=JSON.parse('{"title":"术语表","description":"项目中英文技术术语标准翻译对照表","frontmatter":{"title":"术语表","description":"项目中英文技术术语标准翻译对照表","tags":["基础"],"chapter":99,"order":0},"headers":[],"relativePath":"appendix/terminology.md","filePath":"appendix/terminology.md","lastUpdated":null}'),a={name:"appendix/terminology.md"};function i(c,t,n,l,s,p){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="术语表" tabindex="-1">术语表 <a class="header-anchor" href="#术语表" aria-label="Permalink to &quot;术语表&quot;">​</a></h1><p>本文档收录项目教程中出现的核心术语，按领域分组，提供中英文对照。目的是确保全文术语翻译一致，避免同一概念在不同文章中出现不同译法。</p><h2 id="c-语言特性" tabindex="-1">C++ 语言特性 <a class="header-anchor" href="#c-语言特性" aria-label="Permalink to &quot;C++ 语言特性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>备注</th></tr></thead><tbody><tr><td>RAII (Resource Acquisition Is Initialization)</td><td>资源获取即初始化</td><td>C++ 核心资源管理范式</td></tr><tr><td>move semantics</td><td>移动语义</td><td>C++11 核心特性，避免不必要的拷贝</td></tr><tr><td>rvalue reference</td><td>右值引用</td><td><code>T&amp;&amp;</code>，移动语义的基础</td></tr><tr><td>perfect forwarding</td><td>完美转发</td><td><code>std::forward</code>，保持值类别</td></tr><tr><td>copy elision</td><td>拷贝消除</td><td>编译器优化，省略拷贝/移动操作</td></tr><tr><td>return value optimization (RVO)</td><td>返回值优化</td><td>命名 NRVO，未命名 URVO</td></tr><tr><td>zero-overhead abstraction</td><td>零开销抽象</td><td>C++ 设计哲学，不为未使用的功能付费</td></tr><tr><td>smart pointer</td><td>智能指针</td><td><code>unique_ptr</code>、<code>shared_ptr</code>、<code>weak_ptr</code></td></tr><tr><td>unique pointer</td><td>独占指针</td><td><code>std::unique_ptr</code>，独占所有权</td></tr><tr><td>shared pointer</td><td>共享指针</td><td><code>std::shared_ptr</code>，引用计数共享所有权</td></tr><tr><td>weak pointer</td><td>弱引用指针</td><td><code>std::weak_ptr</code>，打破循环引用</td></tr><tr><td>intrusive pointer</td><td>侵入式指针</td><td>引用计数嵌入对象内部</td></tr><tr><td>constexpr</td><td>常量表达式</td><td>编译期求值，C++11 引入</td></tr><tr><td>consteval</td><td>立即函数</td><td>C++20，强制编译期求值</td></tr><tr><td>constinit</td><td>常量初始化</td><td>C++20，避免静态初始化顺序问题</td></tr><tr><td>SFINAE (Substitution Failure Is Not An Error)</td><td>替换失败并非错误</td><td>模板元编程基础机制</td></tr><tr><td>CRTP (Curiously Recurring Template Pattern)</td><td>奇异递归模板模式</td><td>静态多态惯用法</td></tr><tr><td>template</td><td>模板</td><td>泛型编程基础</td></tr><tr><td>template specialization</td><td>模板特化</td><td>为特定类型提供定制实现</td></tr><tr><td>template instantiation</td><td>模板实例化</td><td>编译器根据模板生成具体代码</td></tr><tr><td>generic programming</td><td>泛型编程</td><td>基于模板的编程范式</td></tr><tr><td>type safety</td><td>类型安全</td><td>编译期捕获类型错误</td></tr><tr><td>type deduction / inference</td><td>类型推断</td><td><code>auto</code>、<code>decltype</code>、模板参数推断</td></tr><tr><td>type traits</td><td>类型特征</td><td><code>&lt;type_traits&gt;</code>，编译期类型查询</td></tr><tr><td>concepts</td><td>概念</td><td>C++20，对模板参数的命名约束</td></tr><tr><td>constraints</td><td>约束</td><td><code>requires</code> 子句，限制模板参数</td></tr><tr><td>lambda expression</td><td>Lambda 表达式</td><td>匿名函数对象，C++11 引入</td></tr><tr><td>structured binding</td><td>结构化绑定</td><td>C++17，<code>auto [a, b] = ...</code></td></tr><tr><td>enum class</td><td>限定作用域枚举</td><td>C++11，类型安全的枚举</td></tr><tr><td>variant</td><td>变体类型</td><td><code>std::variant</code>，类型安全的联合体</td></tr><tr><td>optional</td><td>可选值</td><td><code>std::optional</code>，可能为空的值</td></tr><tr><td>expected</td><td>预期值</td><td>C++23，携带错误信息的返回值</td></tr><tr><td>any</td><td>任意类型</td><td><code>std::any</code>，类型擦除的容器</td></tr><tr><td>scope guard</td><td>作用域守卫</td><td>析构时执行清理动作</td></tr><tr><td>coroutine</td><td>协程</td><td>C++20，<code>co_await</code>/<code>co_yield</code>/<code>co_return</code></td></tr><tr><td>module</td><td>模块</td><td>C++20，替代头文件的编译单元</td></tr><tr><td>range</td><td>范围</td><td>C++20，组合式算法库</td></tr><tr><td>view</td><td>视图</td><td>范围库中的惰性求值适配器</td></tr><tr><td>undefined behavior (UB)</td><td>未定义行为</td><td>标准未规定的行为，结果不可预测</td></tr><tr><td>one definition rule (ODR)</td><td>唯一定义规则</td><td>每个实体在程序中只能有一个定义</td></tr><tr><td>stack unwinding</td><td>栈展开</td><td>异常处理时逐层析构栈上对象</td></tr><tr><td>designated initializer</td><td>指定初始化器</td><td>C++20，<code>{.x = 1, .y = 2}</code></td></tr><tr><td>user-defined literal</td><td>用户自定义字面量</td><td><code>operator&quot;&quot;_suffix</code></td></tr><tr><td>spaceship operator</td><td>飞船运算符</td><td>C++20，<code>&lt;=&gt;</code> 三路比较</td></tr><tr><td>atomic operation</td><td>原子操作</td><td>不可分割的并发安全操作</td></tr><tr><td>memory order</td><td>内存序</td><td>原子操作的排序约束</td></tr><tr><td>lock-free</td><td>无锁</td><td>不使用互斥锁的并发算法</td></tr><tr><td>mutex</td><td>互斥量</td><td>互斥锁，保护共享数据</td></tr><tr><td>semaphore</td><td>信号量</td><td>计数同步原语</td></tr><tr><td>critical section</td><td>临界区</td><td>同一时刻只允许一个线程执行的代码段</td></tr><tr><td>dead lock</td><td>死锁</td><td>多个线程互相等待对方释放资源</td></tr><tr><td>thread</td><td>线程</td><td><code>std::thread</code>，并发执行单元</td></tr><tr><td>span</td><td>视图跨度</td><td><code>std::span</code>，对连续序列的非拥有视图</td></tr><tr><td>EBO (Empty Base Optimization)</td><td>空基类优化</td><td>空类作为基类时不占空间</td></tr><tr><td>static polymorphism</td><td>静态多态</td><td>编译期多态，基于 CRTP 或模板</td></tr></tbody></table><h2 id="嵌入式硬件" tabindex="-1">嵌入式硬件 <a class="header-anchor" href="#嵌入式硬件" aria-label="Permalink to &quot;嵌入式硬件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>备注</th></tr></thead><tbody><tr><td>MCU (Microcontroller Unit)</td><td>微控制器</td><td>集成 CPU、内存、外设的单芯片</td></tr><tr><td>SoC (System on Chip)</td><td>片上系统</td><td>高度集成的单片系统</td></tr><tr><td>register</td><td>寄存器</td><td>硬件可编程的控制/数据单元</td></tr><tr><td>interrupt</td><td>中断</td><td>硬件信号打断 CPU 正常执行流</td></tr><tr><td>interrupt service routine (ISR)</td><td>中断服务程序</td><td>中断触发时执行的函数</td></tr><tr><td>DMA (Direct Memory Access)</td><td>直接内存访问</td><td>外设与内存间无需 CPU 参与的数据传输</td></tr><tr><td>GPIO (General-Purpose I/O)</td><td>通用输入输出</td><td>可配置的数字引脚</td></tr><tr><td>ADC (Analog-to-Digital Converter)</td><td>模数转换器</td><td>模拟信号转数字信号</td></tr><tr><td>DAC (Digital-to-Analog Converter)</td><td>数模转换器</td><td>数字信号转模拟信号</td></tr><tr><td>PWM (Pulse Width Modulation)</td><td>脉宽调制</td><td>通过占空比控制输出</td></tr><tr><td>PLL (Phase-Locked Loop)</td><td>锁相环</td><td>倍频时钟生成电路</td></tr><tr><td>AHB (Advanced High-performance Bus)</td><td>高级高性能总线</td><td>ARM 内部高速总线</td></tr><tr><td>APB (Advanced Peripheral Bus)</td><td>高级外设总线</td><td>ARM 内部外设总线</td></tr><tr><td>clock tree</td><td>时钟树</td><td>从晶振到各模块的时钟分发网络</td></tr><tr><td>pull-up resistor</td><td>上拉电阻</td><td>默认拉高电平</td></tr><tr><td>pull-down resistor</td><td>下拉电阻</td><td>默认拉低电平</td></tr><tr><td>push-pull</td><td>推挽输出</td><td>可主动输出高/低电平</td></tr><tr><td>open-drain</td><td>开漏输出</td><td>只能拉低，需外接上拉电阻</td></tr><tr><td>debounce</td><td>消抖</td><td>去除机械按键的抖动信号</td></tr><tr><td>watchdog</td><td>看门狗</td><td>超时复位 CPU 的安全机制</td></tr><tr><td>EXTI (External Interrupt)</td><td>外部中断</td><td>外部引脚触发的中断</td></tr><tr><td>peripheral</td><td>外设</td><td>MCU 内部独立功能模块</td></tr><tr><td>PCB (Printed Circuit Board)</td><td>印制电路板</td><td>电子元件的载体</td></tr><tr><td>NVIC (Nested Vectored Interrupt Controller)</td><td>嵌套向量中断控制器</td><td>ARM Cortex-M 中断管理器</td></tr><tr><td>HAL (Hardware Abstraction Layer)</td><td>硬件抽象层</td><td>ST 官方外设驱动库</td></tr><tr><td>linker script</td><td>链接脚本</td><td>定义内存布局和段分配</td></tr><tr><td>startup code</td><td>启动代码</td><td>C 运行时初始化，在 main 之前执行</td></tr></tbody></table><h2 id="rtos-实时操作系统" tabindex="-1">RTOS（实时操作系统） <a class="header-anchor" href="#rtos-实时操作系统" aria-label="Permalink to &quot;RTOS（实时操作系统）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>备注</th></tr></thead><tbody><tr><td>RTOS (Real-Time Operating System)</td><td>实时操作系统</td><td>保证响应时间的操作系统</td></tr><tr><td>scheduler</td><td>调度器</td><td>决定哪个任务获得 CPU</td></tr><tr><td>context switch</td><td>上下文切换</td><td>保存/恢复任务执行状态</td></tr><tr><td>priority inversion</td><td>优先级反转</td><td>低优先级任务阻塞高优先级任务</td></tr><tr><td>preemptive scheduling</td><td>抢占式调度</td><td>高优先级任务可抢占低优先级</td></tr><tr><td>cooperative scheduling</td><td>协作式调度</td><td>任务主动让出 CPU</td></tr><tr><td>task / thread</td><td>任务 / 线程</td><td>RTOS 中的执行单元</td></tr><tr><td>tick</td><td>系统节拍</td><td>RTOS 的基本时间单位</td></tr><tr><td>deadline</td><td>截止时间</td><td>任务必须完成的时间点</td></tr><tr><td>queue</td><td>消息队列</td><td>任务间传递数据的 FIFO</td></tr><tr><td>priority inheritance</td><td>优先级继承</td><td>解决优先级反转的协议</td></tr><tr><td>inter-process communication (IPC)</td><td>进程间通信</td><td>任务间数据交换机制</td></tr><tr><td>binary semaphore</td><td>二值信号量</td><td>只有 0/1 两种状态的信号量</td></tr><tr><td>counting semaphore</td><td>计数信号量</td><td>可大于 1 的信号量</td></tr><tr><td>event group</td><td>事件组</td><td>多位标志的事件同步机制</td></tr><tr><td>idle task</td><td>空闲任务</td><td>无其他任务就绪时运行</td></tr><tr><td>real-time</td><td>实时</td><td>确定性的响应时间要求</td></tr></tbody></table><h2 id="工具链" tabindex="-1">工具链 <a class="header-anchor" href="#工具链" aria-label="Permalink to &quot;工具链&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>备注</th></tr></thead><tbody><tr><td>cross-compile</td><td>交叉编译</td><td>在一个平台上生成另一个平台的代码</td></tr><tr><td>toolchain</td><td>工具链</td><td>编译器 + 汇编器 + 链接器的集合</td></tr><tr><td>CMake</td><td>CMake</td><td>跨平台构建系统生成器</td></tr><tr><td>Makefile</td><td>Makefile</td><td>make 构建工具的配置文件</td></tr><tr><td>flash</td><td>烧录</td><td>将程序写入目标芯片</td></tr><tr><td>debug probe</td><td>调试探针</td><td>连接主机与目标板的硬件调试器</td></tr><tr><td>JTAG</td><td>JTAG</td><td>联合测试行动组调试接口</td></tr><tr><td>SWD (Serial Wire Debug)</td><td>串行线调试</td><td>ARM 两线调试接口</td></tr><tr><td>OpenOCD</td><td>OpenOCD</td><td>开源片上调试器</td></tr><tr><td>ELF (Executable and Linkable Format)</td><td>ELF 格式</td><td>可执行可链接格式，编译器输出</td></tr><tr><td>hex</td><td>Intel HEX 格式</td><td>烧录用的文本格式</td></tr><tr><td>objcopy</td><td>对象复制</td><td>格式转换工具（ELF→HEX/BIN）</td></tr><tr><td>compiler flag</td><td>编译器选项</td><td>控制编译行为的命令行参数</td></tr><tr><td>optimization level</td><td>优化等级</td><td><code>-O0</code>/<code>-O1</code>/<code>-O2</code>/<code>-Os</code>/<code>-O3</code></td></tr><tr><td>preprocessor</td><td>预处理器</td><td>处理 <code>#include</code>、<code>#define</code> 等</td></tr><tr><td>linker</td><td>链接器</td><td>将目标文件合并为可执行文件</td></tr><tr><td>assembler</td><td>汇编器</td><td>将汇编代码转为目标文件</td></tr><tr><td>build system</td><td>构建系统</td><td>自动化编译流程的工具</td></tr><tr><td>dependency</td><td>依赖</td><td>一个模块需要另一个模块</td></tr><tr><td>static library</td><td>静态库</td><td>编译时链接的 <code>.a</code>/<code>.lib</code> 文件</td></tr><tr><td>shared library</td><td>动态库</td><td>运行时加载的 <code>.so</code>/<code>.dll</code> 文件</td></tr></tbody></table><h2 id="调试" tabindex="-1">调试 <a class="header-anchor" href="#调试" aria-label="Permalink to &quot;调试&quot;">​</a></h2><table tabindex="0"><thead><tr><th>English</th><th>中文</th><th>备注</th></tr></thead><tbody><tr><td>breakpoint</td><td>断点</td><td>暂停程序执行的标记</td></tr><tr><td>watchpoint</td><td>观察点</td><td>监视内存/变量变化的标记</td></tr><tr><td>trace</td><td>跟踪</td><td>记录程序执行流</td></tr><tr><td>semihosting</td><td>半主机</td><td>目标板通过调试器使用主机 I/O</td></tr><tr><td>ITM (Instrumentation Trace Macrocell)</td><td>指令跟踪宏单元</td><td>ARM Cortex-M 调试输出</td></tr><tr><td>ETM (Embedded Trace Macrocell)</td><td>嵌入式跟踪宏单元</td><td>指令级执行跟踪</td></tr><tr><td>logic analyzer</td><td>逻辑分析仪</td><td>捕获多路数字信号的工具</td></tr><tr><td>oscilloscope</td><td>示波器</td><td>观察电信号波形的仪器</td></tr><tr><td>GDB (GNU Debugger)</td><td>GDB 调试器</td><td>GNU 开源调试器</td></tr><tr><td>core dump</td><td>核心转储</td><td>程序崩溃时的内存快照</td></tr><tr><td>backtrace</td><td>调用栈回溯</td><td>函数调用链的回溯信息</td></tr><tr><td>single-step</td><td>单步执行</td><td>逐条指令/语句执行</td></tr><tr><td>memory leak</td><td>内存泄漏</td><td>分配的内存未被释放</td></tr><tr><td>stack overflow</td><td>栈溢出</td><td>栈空间用尽</td></tr></tbody></table>',12)])])}const m=d(a,[["render",i]]);export{u as __pageData,m as default};
